# =====================================================================
#  Island Biogeography Lab  -  BIOL 215
#  A point-and-click app for species-area analysis.
#  Every tab has a "Show me the R code" panel that reproduces the result.
#
#  To run: open this file in RStudio / Posit Cloud and click "Run App".
#  Packages needed: shiny, bslib, ggplot2, DT, leaflet
# =====================================================================

library(shiny)
library(bslib)
library(ggplot2)
library(DT)
library(leaflet)

# ---- Class password ---------------------------------------------------
# The app opens behind a simple password screen (share the password in Brightspace).
# Only the SHA-256 fingerprint of the lower-case password is stored here, not the password.
# To change it: in R, run  openssl::sha256(tolower("new password"))  (or any SHA-256 tool),
# paste the result below, then re-export. Set to "" to turn the password screen off.
# NOTE: this keeps out casual visitors only. It is not real security: the app runs in the browser.
app_password_sha256 <- "a04adee1d0a335aac59dc15c3107c0e9603b78810970f14e586bb55f695382b4"

gate_ui <- function(hash) {
  if (!nzchar(hash)) return(NULL)
  tagList(
    tags$div(
      id = "gate", class = "gate",
      tags$div(
        class = "gate-card",
        tags$div(class = "gate-title", "BIOL 215 Island Biogeography Lab"),
        tags$p("Enter the class password from Brightspace to open the lab."),
        tags$input(id = "gate_pw", type = "password", class = "form-control form-control-lg",
                   placeholder = "Class password", autocomplete = "off", autocapitalize = "off",
                   autocorrect = "off", spellcheck = "false",
                   onkeydown = "if (event.key === 'Enter') tryGate();"),
        tags$button(type = "button", class = "btn btn-primary btn-lg w-100 mt-3", onclick = "tryGate()",
                    icon("lock-open"), " Open the lab"),
        tags$div(id = "gate_msg", class = "gate-msg", role = "alert")
      )
    ),
    tags$script(HTML(sprintf("
      var GATE_HASH = '%s';
      async function gateSha256(text) {
        var buf = await crypto.subtle.digest('SHA-256', new TextEncoder().encode(text));
        return Array.from(new Uint8Array(buf)).map(function(b) { return b.toString(16).padStart(2, '0'); }).join('');
      }
      // Remember the unlock only for this browser tab: closing the tab or browser asks again (safer on shared lab computers).
      // Also forget any older 'remember on this device' unlock.
      try { localStorage.removeItem('ib_gate'); } catch (e) {}
      function gateRemembered() { try { return sessionStorage.getItem('ib_gate') === GATE_HASH; } catch (e) { return false; } }
      async function tryGate() {
        var box = document.getElementById('gate_pw'), msg = document.getElementById('gate_msg');
        var h = await gateSha256(box.value.trim().toLowerCase());
        if (h === GATE_HASH) {
          try { sessionStorage.setItem('ib_gate', GATE_HASH); } catch (e) {}
          document.getElementById('gate').remove();
        } else {
          msg.textContent = 'That password is not right. Check the Brightspace page and try again.';
          box.focus(); box.select();
        }
      }
      (function() {
        if (gateRemembered()) { var g = document.getElementById('gate'); if (g) g.remove(); }
        else {
          // focus the box once the page has loaded (and again after the app finishes starting)
          [300, 1500, 4000].forEach(function(t) { setTimeout(function() {
            var b = document.getElementById('gate_pw');
            if (b && document.activeElement !== b && document.activeElement && document.activeElement.tagName !== 'INPUT') b.focus();
          }, t); });
        }
      })();
    ", hash)))
  )
}

# ---- Built-in example datasets --------------------------------------
examples <- list(
  hakai = list(
    label = "Hakai 100 Islands, BC Central Coast (plants & birds)",
    file  = "data/hakai_100_islands.csv"
  ),
  gala = list(
    label = "Galápagos Islands (plants)",
    file  = "data/galapagos_plants.csv"
  )
)

# ---- Helper functions -------------------------------------------------

# Pick the first column whose name matches one of the patterns
guess_col <- function(cols, patterns, exclude = character(0)) {
  cols <- setdiff(cols, exclude)
  for (p in patterns) {
    hit <- grep(p, cols, ignore.case = TRUE, value = TRUE)
    if (length(hit)) return(hit[1])
  }
  ""
}

# Turn text like "1,234" into a number; blanks become NA
to_num <- function(x) suppressWarnings(as.numeric(gsub("[,[:space:]]", "", as.character(x))))

# Column names with spaces etc. need `backticks` in R code
q <- function(x) if (identical(make.names(x), x)) x else paste0("`", x, "`")

# Nice number formatting
fmt <- function(x, d = 3) formatC(x, digits = d, format = "fg", flag = "#")
num_lab <- function(x) format(x, big.mark = ",", scientific = FALSE, drop0trailing = TRUE, trim = TRUE)

# Units, guessed from column names (e.g. Area_km2, Dist_SantaCruz_km, Area_ha)
area_div <- function(col) if (grepl("km2|km²|sqkm", col, ignore.case = TRUE)) 1e6 else if (grepl("(_|\\b)ha$|hectare", col, ignore.case = TRUE)) 1e4 else 1
dist_div <- function(col) if (grepl("km", col, ignore.case = TRUE)) 1000 else 1
unit_lab <- function(col, type) {
  if (type == "area") c("1" = "m²", "10000" = "ha", "1e+06" = "km²")[[as.character(area_div(col))]]
  else if (dist_div(col) == 1000) "km" else "m"
}

fmt_p <- function(p) if (p < 0.001) "< 0.001" else formatC(p, digits = 3, format = "f")

# A collapsible "Show me the R code" box
code_box <- function(id) {
  div(
    class = "code-box", id = paste0(id, "_box"),
    div(
      class = "code-box-header",
      span(class = "r-badge", "R"),
      div(
        class = "flex-grow-1",
        div(class = "code-box-title", "See (and change!) the R code behind this page"),
        div(class = "small", "The app is just running these few lines of R. ",
            "Edit the code, then click Run to see what happens. You can't break anything: Reset brings the original back.")
      ),
      tags$button(class = "btn btn-dark code-toggle", type = "button",
                  `data-bs-toggle` = "collapse", `data-bs-target` = paste0("#", id, "_body"),
                  icon("code"), span(class = "label", " Show the code"))
    ),
    div(
      class = "collapse", id = paste0(id, "_body"),
      div(class = "code-wrap",
          tags$button(class = "btn btn-sm btn-light copy-btn", type = "button",
                      onclick = sprintf("copyCode('%s', this)", id), icon("copy"), " Copy"),
          tags$textarea(id = paste0(id, "_edit"), class = "form-control code-editor", rows = 14,
                        spellcheck = "false", autocomplete = "off", autocapitalize = "off", autocorrect = "off"),
          div(class = "d-flex flex-wrap gap-2 align-items-center mt-2",
              tags$button(id = paste0(id, "_run"), type = "button", class = "btn btn-primary fw-bold",
                          onclick = sprintf("runCode('%s')", id), icon("play"), " Run my code"),
              actionButton(paste0(id, "_reset"), "Reset to working code", icon = icon("rotate-left"),
                           class = "btn-outline-danger"),
              span(class = "small text-muted ms-1", "Tip: Ctrl + Enter also runs the code.")),
          div(class = "run-output", uiOutput(paste0(id, "_out"))))
    )
  )
}

# A button for the sidebar that jumps down to (and opens) this page's code
code_link <- function(id) {
  tags$button(class = "btn btn-outline-primary w-100 mt-3 code-link", type = "button",
              onclick = sprintf("openCode('%s')", id),
              icon("code"), " See the R code")
}

code_css_js <- tags$head(
  tags$style(HTML("
    .home-hero { background: linear-gradient(135deg, #6B2E0A 0%, #C55A11 100%); color: #fff;
                 border-radius: 14px; padding: 32px 36px; }
    .home-hero h1 { font-weight: 800; }
    .home-hero .lead { max-width: 760px; }
    .home-hero .btn-primary { background: #F4B183; border-color: #F4B183; color: #6B2E0A; font-weight: 700; }
    .credits h6 { margin-top: .75rem; font-weight: 700; }
    .credits li { margin-bottom: .35rem; }
    .code-box { border: 2px solid #6B2E0A; border-radius: 12px; background: #FBEFE6;
                margin: 1rem 0 2rem; overflow: hidden; }
    .code-box-header { display: flex; align-items: center; gap: 14px; padding: 14px 18px; }
    .code-box-title { font-weight: 700; font-size: 1.1rem; color: #6B2E0A; }
    .r-badge { flex: none; width: 44px; height: 44px; border-radius: 50%; background: #6B2E0A;
               color: #fff; font-weight: 800; font-size: 1.4rem; display: flex;
               align-items: center; justify-content: center; font-family: Georgia, serif; }
    .code-toggle { flex: none; font-weight: 600; white-space: nowrap; }
    .code-wrap { position: relative; padding: 0 18px 18px; }
    .code-editor, .code-editor:focus { background: #1E2430; color: #E8E8E8; border: 2px solid #1E2430;
                     border-radius: 8px; padding: 16px 18px; font-family: Consolas, 'Courier New', monospace;
                     font-size: 0.92rem; line-height: 1.5; resize: vertical; tab-size: 2; }
    .code-editor:focus { border-color: #F4B183; box-shadow: none; }
    .run-output:not(:empty) { margin-top: 12px; }
    .run-out { background: #FFFFFF; border: 1px solid #DDD; border-left: 4px solid #6B8F9C; border-radius: 6px;
               padding: 12px 14px; font-size: 0.88rem; white-space: pre-wrap; margin: 0 0 10px; }
    .run-error { border-left-color: #B5523B; background: #FBEFE6; color: #8A3A26; }
    .run-plot { max-width: 100%; border: 1px solid #DDD; border-radius: 6px; background: #fff; }
    .run-widget { border: 1px solid #DDD; border-radius: 6px; overflow: hidden; }
    .copy-btn { position: absolute; top: 8px; right: 28px; z-index: 2; }
    .code-link { font-weight: 600; }
    /* Tablets (768 px and wider): keep the tabs visible instead of hiding them in a menu; let them wrap */
    @media (min-width: 768px) {
      nav.navbar .navbar-toggler, nav.navbar .navbar-toggle { display: none !important; }
      nav.navbar .navbar-collapse { display: flex !important; flex-basis: auto; flex-grow: 1; }
      nav.navbar .navbar-nav { flex-direction: row; flex-wrap: wrap; }
      nav.navbar .navbar-nav .nav-link { padding-left: .55rem; padding-right: .55rem; }
      .navbar > .container-fluid { flex-wrap: wrap; }
    }
    /* Bigger touch targets on touch screens */
    @media (pointer: coarse) {
      .btn, .form-control, .selectize-input { min-height: 44px; }
      .navbar .nav-link { padding-top: .7rem; padding-bottom: .7rem; }
    }
    .navbar .nav-link { font-size: 1rem; color: #FBEFE6 !important; opacity: .85; }
    .navbar .nav-link.active, .navbar .nav-link:hover { opacity: 1; color: #FFFFFF !important;
                                                        box-shadow: inset 0 -3px 0 #F4B183; }
    .navbar-brand { font-family: Cambria, Caladea, Georgia, serif; font-weight: 700; }
    .gate { position: fixed; inset: 0; z-index: 3000; display: flex; align-items: center; justify-content: center;
            padding: 16px; background: linear-gradient(135deg, #6B2E0A 0%, #C55A11 100%); }
    .gate-card { background: #FFFFFF; border-radius: 16px; padding: 32px 28px; width: 100%; max-width: 420px;
                 box-shadow: 0 12px 40px rgba(0,0,0,.25); text-align: center; }
    .gate-title { font-family: Cambria, Caladea, Georgia, serif; font-weight: 700; font-size: 1.5rem; color: #6B2E0A; margin-bottom: 10px; }
    .gate-msg { color: #B5523B; font-weight: 600; margin-top: 12px; min-height: 1.5em; }
    .flash { animation: flash 1.2s ease-out; }
    .measure-box { border: 2px solid #C55A11; background: #FBEFE6; border-radius: 12px; padding: 14px 14px 16px; }
    .measure-title { font-weight: 800; font-size: 1.1rem; color: #6B2E0A; margin-bottom: 10px; }
    .measure-box .step { font-weight: 600; font-size: .92rem; margin: 10px 0 6px; display: flex; align-items: center; gap: 8px; }
    .step-num { flex: none; width: 24px; height: 24px; border-radius: 50%; background: #C55A11; color: #fff;
                font-size: .8rem; display: inline-flex; align-items: center; justify-content: center; }
    .measure-box .form-group { margin-bottom: 8px; }
    .meas-card { border: 2px solid #C55A11; border-radius: 12px; background: #fff; margin: 1rem 0; overflow: hidden; }
    .meas-card-header { background: #C55A11; color: #fff; padding: 12px 18px; display: flex; align-items: center;
                        gap: 10px; flex-wrap: wrap; }
    .meas-card-title { font-weight: 800; font-size: 1.25rem; }
    .meas-card-body { padding: 16px 18px; }
    @keyframes flash { 0% { box-shadow: 0 0 0 6px rgba(197,90,17,.55); } 100% { box-shadow: 0 0 0 0 rgba(197,90,17,0); } }
    @media (max-width: 576px) { .code-box-header { flex-wrap: wrap; } }
  ")),
  tags$script(HTML("
    function openCode(id) {
      var body = document.getElementById(id + '_body');
      bootstrap.Collapse.getOrCreateInstance(body, {toggle: false}).show();
      var box = document.getElementById(id + '_box');
      box.scrollIntoView({behavior: 'smooth', block: 'start'});
      box.classList.remove('flash'); void box.offsetWidth; box.classList.add('flash');
    }
    function copyCode(id, btn) {
      var text = document.getElementById(id + '_edit').value;
      var done = function() { var old = btn.innerHTML; btn.innerHTML = 'Copied!';
                              setTimeout(function() { btn.innerHTML = old; }, 1500); };
      if (navigator.clipboard && window.isSecureContext) {
        navigator.clipboard.writeText(text).then(done);
      } else {
        var ta = document.createElement('textarea'); ta.value = text; document.body.appendChild(ta);
        ta.select(); document.execCommand('copy'); document.body.removeChild(ta); done();
      }
    }
    document.addEventListener('shown.bs.collapse', function(e) {
      var b = document.querySelector('[data-bs-target=\"#' + e.target.id + '\"] .label');
      if (b) b.textContent = ' Hide the code';
      $(e.target).trigger('shown');   // tell Shiny the code is now visible
    });
    // Scroll to a section and flash it
    // Measuring buttons: drive the map's ruler tool directly, so it works without hovering (tablets, touch screens)
    function measureCtl(sel) { return document.querySelector('#map .leaflet-control-measure ' + sel); }
    function measureStatus(msg) { var s = document.getElementById('meas_status'); if (s) s.textContent = msg; }
    function measureStart() {
      var start = measureCtl('.js-start');
      if (!start) { measureStatus('The map is still loading. Try again in a moment.'); return; }
      start.click();
      document.getElementById('map').scrollIntoView({behavior: 'smooth', block: 'center'});
      measureStatus('Measuring: tap or click points around the island edge (or two points for a distance), then press Finish.');
    }
    function measureFinish() {
      var fin = measureCtl('.js-finish');
      if (fin) fin.click();
      measureStatus('Done. Read the area (or distance) in the box on the map and type it in step 3.');
    }
    function jumpTo(id) {
      var el = document.getElementById(id);
      el.scrollIntoView({behavior: 'smooth', block: 'start'});
      el.classList.remove('flash'); void el.offsetWidth; el.classList.add('flash');
    }
    $(document).on('shiny:connected', function() {
      Shiny.addCustomMessageHandler('flash', function(id) {
        var el = document.getElementById(id);
        if (el) { el.classList.remove('flash'); void el.offsetWidth; el.classList.add('flash'); }
      });
    });
    // Code editor grows to fit its code, so students never have to scroll inside it
    function autoSizeCode(ta) {
      if (!ta || !ta.classList || !ta.classList.contains('code-editor') || ta.offsetParent === null) return;
      ta.style.height = 'auto'; ta.style.height = (ta.scrollHeight + 4) + 'px';
    }
    document.addEventListener('input', function(e) { autoSizeCode(e.target); });
    $(document).on('shiny:updateinput', function(e) { setTimeout(function() { autoSizeCode(e.target); }, 0); });
    document.addEventListener('shown.bs.collapse', function(e) { autoSizeCode(e.target.querySelector('.code-editor')); });
    // Send exactly what is in the editor right now to R
    function runCode(id) {
      var code = document.getElementById(id + '_edit').value;
      Shiny.setInputValue(id + '_submit', {code: code, t: Date.now()}, {priority: 'event'});
    }
    // In the code editor: Tab inserts spaces, Ctrl/Cmd + Enter runs the code
    document.addEventListener('keydown', function(e) {
      var ta = e.target;
      if (!ta.classList || !ta.classList.contains('code-editor')) return;
      if (e.key === 'Tab') {
        e.preventDefault();
        var s = ta.selectionStart;
        ta.value = ta.value.slice(0, s) + '  ' + ta.value.slice(ta.selectionEnd);
        ta.selectionStart = ta.selectionEnd = s + 2;
        $(ta).trigger('change');
      } else if (e.key === 'Enter' && (e.ctrlKey || e.metaKey)) {
        e.preventDefault();
        runCode(ta.id.replace(/_edit$/, ''));
      }
    });
    document.addEventListener('hidden.bs.collapse', function(e) {
      var b = document.querySelector('[data-bs-target=\"#' + e.target.id + '\"] .label');
      if (b) b.textContent = ' Show the code';
    });
  "))
)

# ---- User interface ---------------------------------------------------
ui <- page_navbar(
  title = "BIOL 215 Island Biogeography Lab",
  theme = bs_theme(
    version = 5,
    # BIOL 215 lab palette (matches the Lab 5 & 6 slides and manuals)
    bg = "#FFFFFF", fg = "#1A1A1A",
    primary = "#C55A11", secondary = "#7A6F5A", success = "#6B8F9C",
    info = "#6B8F9C", warning = "#D9A441", danger = "#B5523B", light = "#FBEFE6", dark = "#6B2E0A",
    base_font = font_collection("Calibri", "Carlito", "Segoe UI", "Helvetica Neue", "Arial", "sans-serif"),
    heading_font = font_collection("Cambria", "Caladea", "Georgia", "serif"),
    "link-color" = "#C55A11"
  ),
  navbar_options = navbar_options(bg = "#6B2E0A", theme = "dark"),
  fillable = FALSE,
  header = tagList(code_css_js, tags$head(tags$meta(name = "robots", content = "noindex, nofollow")),
                   gate_ui(app_password_sha256)),
  id = "nav",

  # ---------- HOME ----------
  nav_panel(
    "Home", icon = icon("house"),
    div(
      class = "container-lg py-3",
      div(class = "home-hero",
        h1("BIOL 215 Island Biogeography Lab"),
        p(class = "lead",
          "Why do bigger islands hold more species? In this lab you will map real islands, measure them yourself, ",
          "and test the species–area relationship (S = cA", tags$sup("z"), ") with data from British Columbia and the Galápagos."),
        actionButton("go_start", "Start the lab", icon = icon("arrow-right"), class = "btn-primary btn-lg")
      ),

      h4(class = "mt-4", "How the lab works"),
      layout_columns(
        col_widths = breakpoints(sm = 12, md = 6, lg = c(2, 2, 3, 3, 2)),
        fill = FALSE,
        card(card_body(h6(icon("table"), " 1 · Data"), p(class = "small mb-0", "Choose a dataset and tell the app which column is which."))),
        card(card_body(h6(icon("map"), " 2 · Map"), p(class = "small mb-0", "Explore the islands and measure their area and isolation with the ruler tool."))),
        card(card_body(h6(icon("chart-line"), " 3 · Species–Area"), p(class = "small mb-0", "Plot species vs. area on log–log axes and find z."))),
        card(card_body(h6(icon("magnifying-glass"), " 4 · Beyond Area"), p(class = "small mb-0", "Do isolation or marine nutrients explain what area doesn't?"))),
        card(card_body(h6(icon("calculator"), " 5 · Predict"), p(class = "small mb-0", "Predict species numbers and the cost of habitat loss.")))
      ),
      p(class = "small text-muted mt-2", icon("code"),
        " On every page, the orange ", strong("See the R code"), " button shows the R code behind it. You can edit and run it, and ",
        strong("Reset to working code"), " brings the original back."),

      h4(class = "mt-4", "The islands"),
      layout_columns(
        col_widths = breakpoints(sm = 12, md = 6),
        fill = FALSE,
        card(
          card_header(icon("tree"), " Hakai 100 Islands · Central Coast, British Columbia"),
          card_body(
            p("92 small islands near Calvert Island, from about 120 m² to 288 hectares. Researchers with the Hakai Institute's ",
              "100 Islands Project surveyed plants and breeding birds on each island (2015–2017), along with ",
              "how much seaweed (wrack) washes ashore and soil nitrogen isotopes (δ15N), which trace nutrients from the sea."),
            p(class = "small text-muted mb-0",
              "Columns: plant species (rarefied and observed), bird species, area, distance to nearest land, slope, wrack, soil δ15N, and latitude/longitude.")
          )
        ),
        card(
          card_header(icon("sun"), " Galápagos Islands · Ecuador"),
          card_body(
            p("30 islands, from tiny islets to Isabela (4,669 km²). This is a classic species–area dataset of plant species counts, ",
              "with island area, elevation, and distances to neighbouring islands. Use it to compare an isolated oceanic ",
              "archipelago with near-shore BC islands."),
            p(class = "small text-muted mb-0",
              "Columns: species, endemic species, area (km²), elevation, distance to nearest island and to Santa Cruz, and latitude/longitude.")
          )
        )
      ),

      h4(class = "mt-4", id = "credits", "Data sources & credits"),
      card(
        card_body(
          class = "credits",
          h6("Hakai 100 Islands data (CC BY 4.0)"),
          tags$ul(
            tags$li("Plant data: Hakai Institute, ",
                    em("100 Islands Research Program Terrestrial Vegetation Data, BC Central Coast, 2015–2017"), ". ",
                    tags$a(href = "https://doi.org/10.21966/CZ48-D388", target = "_blank", "doi:10.21966/CZ48-D388")),
            tags$li("Obrist, D.S. et al. (2022). Scale-dependent effects of marine subsidies on the island biogeographic patterns of plants. ",
                    em("Ecology and Evolution"), " 12: e9270. ",
                    tags$a(href = "https://doi.org/10.1002/ece3.9270", target = "_blank", "doi:10.1002/ece3.9270")),
            tags$li("Bird data: Hakai Institute, ",
                    em("Avian and paired vegetation data from the 100 Islands Project, BC Central Coast, 2015–2017"), ". ",
                    tags$a(href = "https://doi.org/10.21966/10tk-4956", target = "_blank", "doi:10.21966/10tk-4956")),
            tags$li("Obrist, D.S. et al. (2020). Marine subsidies mediate patterns in avian island biogeography. ",
                    em("Proceedings of the Royal Society B"), " 287: 20200108. ",
                    tags$a(href = "https://doi.org/10.1098/rspb.2020.0108", target = "_blank", "doi:10.1098/rspb.2020.0108")),
            tags$li("For this lab, the island-level plant and bird files were merged by island code, observed plant species were counted ",
                    "from the plot data, and UTM coordinates were converted to latitude/longitude.")
          ),
          p(class = "small",
            "The 100 Islands study area is in the territories of the Heiltsuk and Wuikinuxv Nations."),
          h6("Galápagos data"),
          tags$ul(
            tags$li("Johnson, M.P. & Raven, P.H. (1973). Species number and endemism: the Galápagos Archipelago revisited. ",
                    em("Science"), " 179: 893–895. Data as distributed in the ",
                    tags$a(href = "https://cran.r-project.org/package=faraway", target = "_blank", "faraway"),
                    " R package (J. Faraway)."),
            tags$li("Island locations: © ", tags$a(href = "https://www.openstreetmap.org/copyright", target = "_blank", "OpenStreetMap contributors"),
                    " (ODbL). The Gardner islet near Española is not in OpenStreetMap; its position is approximate, from ",
                    tags$a(href = "https://whalesite.org/GT/TOURISM/MARINESITES.htm", target = "_blank", "WhaleSite.org"), ".")
          ),
          h6("Maps"),
          tags$ul(
            tags$li("Satellite imagery: Esri World Imagery. Source: Esri, i-cubed, USDA, USGS, AEX, GeoEye, Getmapping, Aerogrid, IGN, IGP, UPR-EGP, and the GIS User Community."),
            tags$li("Street map: © ", tags$a(href = "https://www.openstreetmap.org/copyright", target = "_blank", "OpenStreetMap contributors"), "."),
            tags$li("Map and measuring tools: ", tags$a(href = "https://leafletjs.com", target = "_blank", "Leaflet"),
                    " with the leaflet-measure plugin, via the R package ",
                    tags$a(href = "https://rstudio.github.io/leaflet/", target = "_blank", "leaflet"), ".")
          ),
          h6("Software"),
          p(class = "mb-0",
            "Built with R and the packages shiny, bslib, ggplot2, DT, and leaflet. Made for BIOL 215.")
        )
      )
    )
  ),

  # ---------- 1. DATA ----------
  nav_panel(
    "1 · Data",
    layout_sidebar(
      sidebar = sidebar(open = "always", 
        width = 330,
        radioButtons("src", "Where is your data?",
          c("Example: Hakai 100 Islands (BC)" = "hakai",
            "Example: Galápagos Islands"      = "gala",
            "Upload my own CSV file"          = "upload")),
        conditionalPanel("input.src == 'upload'",
          fileInput("file", NULL, accept = ".csv", buttonLabel = "Choose CSV..."),
          helpText("Using Excel? Choose File > Save As > CSV first. ",
                   "One row per island, with columns for island name, number of species, and area.")),
        hr(),
        h6("Tell the app which column is which"),
        selectInput("col_name", "Island name", NULL),
        selectInput("col_S", "Number of species (S)", NULL),
        selectInput("col_A", "Island area (A)", NULL),
        selectInput("col_D", "Isolation (distance)", NULL),
        selectInput("col_X", "Another variable to explore (optional)", NULL),
        code_link("code_data")
      ),
      uiOutput("data_check"),
      card(card_header("Your data"), DTOutput("table")),
      code_box("code_data")
    )
  ),

  # ---------- 2. MAP ----------
  nav_panel(
    "2 · Map",
    layout_sidebar(
      sidebar = sidebar(open = "always", width = 330,
        div(
          class = "measure-box",
          div(class = "measure-title", icon("ruler-combined"), " Measure an island yourself"),
          div(class = "step", span(class = "step-num", "1"), "Pick an island (or click one on the map)"),
          selectInput("meas_island", NULL, NULL),
          div(class = "step", span(class = "step-num", "2"), "Measure it on the map"),
          div(class = "d-flex gap-2 mb-1",
              tags$button(id = "meas_start", type = "button", class = "btn btn-primary btn-sm flex-fill",
                          onclick = "measureStart()", icon("ruler-combined"), " Start measuring"),
              tags$button(id = "meas_finish", type = "button", class = "btn btn-outline-primary btn-sm flex-fill",
                          onclick = "measureFinish()", icon("check"), " Finish")),
          div(id = "meas_status", class = "small text-muted mb-1",
              "Zoom in, click Start measuring, then tap or click points around the island's edge."),
          actionLink("meas_help", "How do I measure?", icon = icon("circle-question"), class = "small d-block mb-2"),
          div(class = "step", span(class = "step-num", "3"), "Type in what the ruler shows"),
          numericInput("meas_area", "Area (m²)", NA, min = 0),
          numericInput("meas_dist", "Distance to nearest land (m)", NA, min = 0),
          uiOutput("meas_units_note"),
          div(class = "step", span(class = "step-num", "4"), "Save it"),
          actionButton("meas_add", "Add to My Measurements", icon = icon("plus"), class = "btn-primary w-100 fw-bold py-2"),
          tags$button(class = "btn btn-outline-primary w-100 mt-2", type = "button",
                      onclick = "jumpTo('meas_card')",
                      icon("list-check"), " My Measurements ",
                      span(class = "badge bg-primary", textOutput("meas_n", inline = TRUE)))
        ),
        hr(),
        selectInput("map_colour", "Colour islands by", NULL),
        checkboxInput("map_size", "Bigger circles = bigger islands", TRUE),
        radioButtons("basemap", "Background", c("Satellite" = "sat", "Map" = "street"), inline = TRUE),
        code_link("code_map")
      ),
      card(
        full_screen = TRUE,
        card_header("Study islands"),
        leafletOutput("map", height = 520)
      ),
      div(
        id = "meas_card", class = "meas-card",
        div(class = "meas-card-header",
            icon("ruler-combined"),
            span(class = "meas-card-title", "My Measurements"),
            span(class = "badge rounded-pill bg-light text-primary ms-1", textOutput("meas_n2", inline = TRUE)),
            span(class = "ms-auto small", "How close did you get to the published values?")),
        div(class = "meas-card-body",
            layout_columns(
              col_widths = breakpoints(sm = 12, lg = c(7, 5)),
              fill = FALSE,
              DTOutput("meas_table"),
              plotOutput("meas_plot", height = 300)
            ),
            div(class = "d-flex flex-wrap gap-2 mt-3",
                downloadButton("dl_meas", "Download My Measurements (CSV)", class = "btn-primary"),
                actionButton("meas_clear", "Clear all", icon = icon("trash"), class = "btn-outline-danger")))
      ),
      code_box("code_map")
    )
  ),

  # ---------- 3. SPECIES-AREA ----------
  nav_panel(
    "3 · Species–Area",
    layout_sidebar(
      sidebar = sidebar(open = "always", 
        checkboxInput("loglog", "Log–log axes", TRUE),
        checkboxInput("showfit", "Show best-fit line", TRUE),
        checkboxInput("labels", "Label islands", FALSE),
        helpText("Tip: click a point to see which island it is."),
        downloadButton("dl_sa", "Download plot"),
        code_link("code_sa")
      ),
      layout_columns(
        fill = FALSE,
        value_box("z (slope)", textOutput("z"), theme = "primary"),
        value_box("c (intercept)", textOutput("c"), theme = "secondary"),
        value_box("R²", textOutput("r2"), theme = "info"),
        value_box("Islands used", textOutput("n"), theme = "light")
      ),
      card(
        card_header(uiOutput("eqn")),
        plotOutput("sa_plot", height = 430, click = "sa_click"),
        uiOutput("sa_clicked")
      ),
      card(
        card_header("What does this mean?"),
        uiOutput("sa_interpret")
      ),
      code_box("code_sa")
    )
  ),

  # ---------- 4. BEYOND AREA ----------
  nav_panel(
    "4 · Beyond Area",
    layout_sidebar(
      sidebar = sidebar(open = "always", 
        radioButtons("xvar", "Compare the leftover variation with:",
                     c("Isolation (distance)" = "D", "My other variable" = "X")),
        checkboxInput("logx", "Log scale for x-axis", TRUE),
        downloadButton("dl_resid", "Download results table"),
        code_link("code_resid")
      ),
      card(
        card_header("Which islands have more (or fewer) species than their area predicts?"),
        p(class = "small text-muted",
          "Each point is an island. Above the dashed line = more species than expected for its size; ",
          "below = fewer. If the x-variable matters, the points will slope up or down."),
        plotOutput("resid_plot", height = 400),
        uiOutput("resid_stats")
      ),
      card(card_header("Islands ranked by how far they are from the prediction"), DTOutput("resid_table")),
      code_box("code_resid")
    )
  ),

  # ---------- 5. PREDICT ----------
  nav_panel(
    "5 · Predict",
    layout_columns(
      col_widths = c(6, 6),
      card(
        card_header("How many species should an island have?"),
        numericInput("new_area", "Island area (same units as your data)", value = 10, min = 0),
        uiOutput("pred_out"),
        code_link("code_pred")
      ),
      card(
        card_header("Habitat loss: how many species will eventually disappear?"),
        sliderInput("loss", "Percent of habitat destroyed", 0, 99, 50, post = "%"),
        uiOutput("loss_out"),
        plotOutput("loss_plot", height = 260)
      )
    ),
    code_box("code_pred")
  ),

  nav_spacer()
)

# ---- Server -------------------------------------------------------------
server <- function(input, output, session) {

  code_r <- list()   # the R code shown on each tab (filled in below)

  observeEvent(input$go_start, nav_select("nav", "1 · Data"))

  raw      <- reactiveVal(read.csv(examples$hakai$file, check.names = FALSE))
  read_cmd <- reactiveVal(sprintf('dat <- read.csv("%s")', examples$hakai$file))

  # --- loading data ---
  observeEvent(input$src, {
    if (input$src %in% names(examples)) {
      f <- examples[[input$src]]$file
      raw(read.csv(f, check.names = FALSE))
      read_cmd(sprintf('dat <- read.csv("%s")', f))
    }
  }, ignoreInit = TRUE)

  observeEvent(input$file, {
    tryCatch({
      raw(read.csv(input$file$datapath, check.names = FALSE))
      # Keep a copy in the project so the R code (and the Run button) can read it too
      dir.create("my_data", showWarnings = FALSE)
      dest <- file.path("my_data", basename(input$file$name))
      ok <- file.copy(input$file$datapath, dest, overwrite = TRUE)
      read_cmd(if (ok) sprintf('dat <- read.csv("%s")', dest)
               else sprintf('dat <- read.csv("%s")   # upload this file to your project first', input$file$name))
    }, error = function(e) showNotification("Couldn't read that file. Is it a .csv?", type = "error"))
  })

  # --- guess which column is which whenever new data arrives ---
  observeEvent(raw(), {
    cols <- names(raw())
    nm <- guess_col(cols, c("^island$", "island", "name", "site"))
    S  <- guess_col(cols, c("^species$", "plant_species$", "species", "richness", "^S$"))
    A  <- guess_col(cols, c("^area", "area"))
    D  <- guess_col(cols, c("main", "dist", "isol", "near"), exclude = c(A, S))
    X  <- guess_col(cols, c("elev", "wrack", "d15n", "slope", "habitat"), exclude = c(A, S, D))
    none <- c("(none)" = "")
    updateSelectInput(session, "col_name", choices = c(none, cols), selected = nm)
    updateSelectInput(session, "col_S", choices = cols, selected = S)
    updateSelectInput(session, "col_A", choices = cols, selected = A)
    updateSelectInput(session, "col_D", choices = c(none, cols), selected = D)
    updateSelectInput(session, "col_X", choices = c(none, cols), selected = X)
  })

  # --- tidy data used by every analysis ---
  clean <- reactive({
    d <- raw()
    req(input$col_S, input$col_A, all(c(input$col_S, input$col_A) %in% names(d)))
    get <- function(col) if (nzchar(col) && col %in% names(d)) to_num(d[[col]]) else rep(NA_real_, nrow(d))
    out <- data.frame(
      Island = if (nzchar(input$col_name) && input$col_name %in% names(d))
                 as.character(d[[input$col_name]]) else paste("Row", seq_len(nrow(d))),
      S = get(input$col_S), A = get(input$col_A),
      D = get(input$col_D), X = get(input$col_X)
    )
    out$ok <- is.finite(out$S) & is.finite(out$A) & out$S > 0 & out$A > 0
    out
  })

  used <- reactive(subset(clean(), ok))

  model <- reactive({
    d <- used()
    validate(need(nrow(d) >= 3,
      "You need at least 3 islands with species > 0 and area > 0 to fit a line. Check your column choices on the Data tab."))
    lm(log10(S) ~ log10(A), data = d)
  })

  fitted_dat <- reactive({
    d <- used(); m <- model()
    d$Predicted <- 10^fitted(m)
    d$Residual  <- residuals(m)
    d
  })

  z  <- reactive(unname(coef(model())[2]))
  cc <- reactive(unname(10^coef(model())[1]))

  # ================= TAB 2: MAP =================
  map_cols <- reactive({
    cols <- names(raw())
    lat <- guess_col(cols, c("^lat"))
    lon <- guess_col(cols, c("^lon", "^lng"))
    validate(need(nzchar(lat) && nzchar(lon),
      "This dataset has no Latitude / Longitude columns, so it can't be mapped. Choose the Hakai example on the Data tab, or upload a CSV that includes Latitude and Longitude."))
    list(lat = lat, lon = lon, name = guess_col(cols, c("^island$", "island", "name", "site")))
  })

  island_names <- reactive({
    d <- raw(); nm <- guess_col(names(d), c("^island$", "island", "name", "site"))
    if (nzchar(nm)) as.character(d[[nm]]) else paste("Row", seq_len(nrow(d)))
  })

  observeEvent(raw(), {
    d <- raw(); cols <- names(d)
    numc <- cols[vapply(d, function(x) is.numeric(x) && any(is.finite(x)), logical(1))]
    numc <- numc[!grepl("^lat|^lon|^lng", numc, ignore.case = TRUE)]
    updateSelectInput(session, "map_colour", choices = numc,
                      selected = guess_col(numc, c("^plant_species$", "^species$", "species")))
    updateSelectInput(session, "meas_island", choices = island_names())
  })

  observeEvent(input$map_marker_click, {
    updateSelectInput(session, "meas_island", selected = input$map_marker_click$id)
  })

  output$map <- renderLeaflet({
    mc <- map_cols(); d <- raw()
    req(input$map_colour %in% names(d))
    lat <- to_num(d[[mc$lat]]); lon <- to_num(d[[mc$lon]])
    val <- to_num(d[[input$map_colour]])
    pal <- colorNumeric("viridis", domain = val, na.color = "#BBBBBB")

    radius <- rep(7, nrow(d))
    a <- if (input$col_A %in% names(d)) to_num(d[[input$col_A]]) else NULL
    if (isTRUE(input$map_size) && !is.null(a) && any(a > 0, na.rm = TRUE)) {
      la <- log10(pmax(a, min(a[a > 0], na.rm = TRUE)))
      radius <- 4 + 12 * (la - min(la, na.rm = TRUE)) / diff(range(la, na.rm = TRUE))
      radius[!is.finite(radius)] <- 5
    }

    # Popup: every column for that island
    popups <- vapply(seq_len(nrow(d)), function(i) {
      rows <- paste0("<tr><td style='padding-right:8px;color:#666'>", names(d), "</td><td><b>",
                     htmltools::htmlEscape(as.character(unlist(d[i, ]))), "</b></td></tr>", collapse = "")
      paste0("<table style='font-size:12px'>", rows, "</table>")
    }, character(1))

    tiles <- if (input$basemap == "sat") providers$Esri.WorldImagery else providers$OpenStreetMap

    m <- leaflet(options = leafletOptions(maxZoom = 19)) |>
      addProviderTiles(tiles, options = providerTileOptions(maxNativeZoom = 18, maxZoom = 19)) |>
      addCircleMarkers(lng = lon, lat = lat, layerId = island_names(), radius = radius,
                       color = "white", weight = 1, fillColor = pal(val), fillOpacity = 0.9,
                       label = island_names(), popup = popups) |>
      addLegend("bottomright", pal = pal, values = val, title = input$map_colour, opacity = 0.9) |>
      addScaleBar("bottomleft", options = scaleBarOptions(imperial = FALSE)) |>
      addMeasure(position = "topright",
                 primaryLengthUnit = "meters", secondaryLengthUnit = "kilometers",
                 primaryAreaUnit = "sqmeters", secondaryAreaUnit = "hectares",
                 activeColor = "#F4B183", completedColor = "#C55A11")

    # Keep the current view when the colours change; otherwise zoom to fit all islands
    z <- isolate(input$map_zoom); ctr <- isolate(input$map_center)
    if (!is.null(z) && !is.null(ctr)) m |> setView(ctr$lng, ctr$lat, z)
    else m |> fitBounds(min(lon, na.rm = TRUE), min(lat, na.rm = TRUE), max(lon, na.rm = TRUE), max(lat, na.rm = TRUE))
  })

  # --- student measurements ---
  meas <- reactiveVal(data.frame(Island = character(), Measured_area = numeric(), Published_area = numeric(),
                                 Measured_distance = numeric(), Published_distance = numeric()))

  observeEvent(input$meas_add, {
    req(nzchar(input$meas_island))
    if (!is.finite(input$meas_area) && !is.finite(input$meas_dist)) {
      showNotification("Type in at least one measurement first.", type = "warning"); return()
    }
    d <- raw(); i <- match(input$meas_island, island_names())
    pub <- function(col) if (nzchar(col) && col %in% names(d)) to_num(d[[col]])[i] else NA_real_
    # The ruler reports m² and m; convert to the units used in the data columns
    new <- data.frame(Island = input$meas_island,
                      Measured_area = input$meas_area / area_div(input$col_A), Published_area = pub(input$col_A),
                      Measured_distance = input$meas_dist / dist_div(input$col_D), Published_distance = pub(input$col_D))
    old <- meas(); old <- old[old$Island != input$meas_island, ]
    meas(rbind(old, new))
    showNotification(sprintf("Added %s to My Measurements (%d island%s so far).", input$meas_island,
                             nrow(meas()), if (nrow(meas()) == 1) "" else "s"), type = "message")
    session$sendCustomMessage("flash", "meas_card")
    updateNumericInput(session, "meas_area", value = NA)
    updateNumericInput(session, "meas_dist", value = NA)
  })

  output$meas_n  <- renderText(nrow(meas()))
  output$meas_n2 <- renderText(sprintf("%d island%s", nrow(meas()), if (nrow(meas()) == 1) "" else "s"))

  observeEvent(input$meas_clear, {
    showModal(modalDialog(
      title = "Clear all your measurements?",
      "This removes every island from My Measurements. Download them first if you want to keep them.",
      footer = tagList(modalButton("Cancel"), actionButton("meas_clear_yes", "Yes, clear them", class = "btn-danger"))
    ))
  })
  observeEvent(input$meas_clear_yes, { meas(meas()[0, ]); removeModal() })

  observeEvent(input$meas_help, {
    showModal(modalDialog(
      title = tagList(icon("ruler-combined"), " How to measure an island"),
      easyClose = TRUE, size = "l",
      tags$ol(
        tags$li("Tap or click an island's circle to select it and see its data."),
        tags$li("Zoom in (+ button, mouse wheel, or pinch on a tablet) until you can clearly see the island's shoreline. The satellite background works best."),
        tags$li(HTML("Press <b>Start measuring</b> in the orange box.")),
        tags$li(HTML("<b>Area:</b> tap or click points all the way around the vegetated edge of the island, then press <b>Finish</b>. A box on the map shows the area. Write it down in <b>m²</b>.")),
        tags$li(HTML("<b>Distance:</b> press <b>Start measuring</b> again, tap once on the island's shore and once on the nearest shore of other land, then press <b>Finish</b>. Write down the distance in <b>m</b>.")),
        tags$li(HTML("Type both numbers into step 3 and click <b>Add to My Measurements</b>."))
      ),
      p(class = "small text-muted mb-0",
        "The circles mark the centre of each island, not its outline. Some Hakai islands are tiny (about 100 m²), so zoom in a lot! ",
        "(On a computer you can also use the ruler icon in the top-right corner of the map.)"),
      footer = modalButton("Got it")
    ))
  })

  output$meas_units_note <- renderUI({
    a <- unit_lab(input$col_A, "area"); d <- unit_lab(input$col_D, "dist")
    note <- if (a != "m²" || d != "m")
      sprintf("Type m² and m, exactly as the ruler shows. The app converts them to %s and %s to match this dataset.", a, d)
      else "Type the numbers exactly as the ruler shows them."
    if (nzchar(input$col_D)) note <- paste0(note, " Distance is compared with ", input$col_D, ".")
    helpText(class = "small mt-0", note)
  })

  output$meas_table <- renderDT({
    m <- meas()
    m$Area_diff_pct <- round(100 * (m$Measured_area - m$Published_area) / m$Published_area, 1)
    m$Dist_diff_pct <- round(100 * (m$Measured_distance - m$Published_distance) / m$Published_distance, 1)
    datatable(m[, c("Island", "Measured_area", "Published_area", "Area_diff_pct",
                    "Measured_distance", "Published_distance", "Dist_diff_pct")],
              rownames = FALSE,
              colnames = c("Island", paste0("My area (", unit_lab(input$col_A, "area"), ")"), "Published area", "% diff",
                           paste0("My distance (", unit_lab(input$col_D, "dist"), ")"), "Published distance", "% diff"),
              options = list(dom = "t", pageLength = 50, scrollX = TRUE,
                             language = list(emptyTable = "No measurements yet. Measure an island on the map!")))
  })

  output$meas_plot <- renderPlot({
    m <- subset(meas(), is.finite(Measured_area) & is.finite(Published_area) & Measured_area > 0)
    validate(need(nrow(m) > 0, "Your measured vs. published areas will be plotted here."))
    lims <- range(c(m$Measured_area, m$Published_area))
    ggplot(m, aes(Published_area, Measured_area)) +
      geom_abline(slope = 1, intercept = 0, linetype = "dashed", colour = "grey50") +
      geom_point(size = 3, colour = "#C55A11") +
      geom_text(aes(label = Island), vjust = -0.9, size = 3.2) +
      scale_x_log10(labels = num_lab, limits = lims, expand = expansion(mult = 0.25)) +
      scale_y_log10(labels = num_lab, limits = lims, expand = expansion(mult = 0.25)) +
      coord_cartesian(clip = "off") +
      labs(x = "Published area", y = "My measured area", subtitle = "Dashed line = perfect agreement") +
      theme_minimal(base_size = 12)
  }, res = 96)

  output$dl_meas <- downloadHandler(
    filename = function() "my_island_measurements.csv",
    content = function(file) write.csv(meas(), file, row.names = FALSE)
  )

  code_r$code_map <- reactive({
    mc <- map_cols()
    paste0(
      "# Lines starting with # are comments: notes for people. R skips them.\n\n",
      "# Load the leaflet package, which draws interactive maps\n",
      "library(leaflet)\n\n",
      "# Read the spreadsheet of islands into R and call it 'dat'\n",
      read_cmd(), "\n\n",
      "# Build the map one layer at a time. The |> symbol means\n",
      "# 'take the result so far and pass it to the next step'.\n",
      "leaflet(dat) |>\n",
      "  # 1. a satellite photo background\n",
      "  addProviderTiles(providers$Esri.WorldImagery) |>\n",
      "  # 2. one circle per island, placed by its longitude (lng) and latitude (lat);\n",
      "  #    ~ means 'use this column of dat'. radius sets the circle size.\n",
      sprintf("  addCircleMarkers(lng = ~%s, lat = ~%s,\n", q(mc$lon), q(mc$lat)),
      sprintf("                   label = ~%s, radius = 6) |>\n", if (nzchar(mc$name)) q(mc$name) else "rownames(dat)"),
      "  # 3. the ruler tool, reporting distances in metres and areas in square metres\n",
      "  addMeasure(primaryLengthUnit = \"meters\", primaryAreaUnit = \"sqmeters\")\n")
  })

  # ================= TAB 1: DATA =================
  output$table <- renderDT({
    datatable(raw(), rownames = FALSE, options = list(pageLength = 10, scrollX = TRUE))
  })

  output$data_check <- renderUI({
    d <- clean()
    n_ok <- sum(d$ok)
    missing <- sum(!is.finite(d$S) | !is.finite(d$A))
    zeros <- sum(is.finite(d$S) & is.finite(d$A) & (d$S <= 0 | d$A <= 0))
    msgs <- tagList(strong(sprintf("%d islands ready to analyse.", n_ok)))
    if (missing > 0) msgs <- tagList(msgs, br(), sprintf("%d row(s) skipped: species or area is blank / not a number.", missing))
    if (zeros > 0) msgs <- tagList(msgs, br(), sprintf("%d row(s) skipped: 0 species or 0 area (you can't take the log of 0).", zeros))
    div(class = if (missing + zeros > 0) "alert alert-warning" else "alert alert-success", msgs)
  })

  code_r$code_data <- reactive({
    paste0(
      "# Lines starting with # are comments: notes for people. R skips them.\n\n",
      "# Read the spreadsheet (a .csv file) into R and store it under the name 'dat'.\n",
      "# The <- arrow means 'store the result on the right under the name on the left'.\n",
      read_cmd(), "\n\n",
      "# Show the first 6 rows, to check the data look right\n",
      "head(dat)\n\n",
      "# Count the rows: one row per island\n",
      "nrow(dat)\n\n",
      "# Summarise one column: smallest, quartiles, median, mean, and largest value.\n",
      "# dat$Column means 'the column called Column inside dat'.\n",
      "summary(dat$", q(input$col_S), ")\n")
  })

  # ================= TAB 2: SPECIES-AREA =================
  output$z  <- renderText(fmt(z()))
  output$c  <- renderText(fmt(cc()))
  output$r2 <- renderText(fmt(summary(model())$r.squared, 2))
  output$n  <- renderText(nrow(used()))

  output$eqn <- renderUI({
    p <- summary(model())$coefficients[2, 4]
    ptxt <- if (p < 0.001) "p &lt; 0.001" else paste("p =", fmt_p(p))
    HTML(sprintf("Best fit: &nbsp; <b>S = %s × A<sup>%s</sup></b> &nbsp;&nbsp; <span class='text-muted small'>(%s)</span>",
                 fmt(cc()), fmt(z()), ptxt))
  })

  sa_plot_obj <- reactive({
    d <- fitted_dat()
    p <- ggplot(d, aes(A, S)) +
      geom_point(size = 3, colour = "#C55A11", alpha = 0.8) +
      labs(x = paste0("Island area (", input$col_A, ")"),
           y = paste0("Number of species (", input$col_S, ")")) +
      theme_minimal(base_size = 15)
    if (input$showfit) {
      grid <- data.frame(A = 10^seq(log10(min(d$A)), log10(max(d$A)), length.out = 200))
      grid$S <- cc() * grid$A^z()
      p <- p + geom_line(data = grid, colour = "#6B2E0A", linewidth = 1.2)
    }
    if (input$labels) p <- p + geom_text(aes(label = Island), vjust = -0.9, size = 3.3, colour = "grey30")
    if (input$loglog) p <- p + scale_x_log10(labels = num_lab) + scale_y_log10(labels = num_lab)
    else p <- p + scale_x_continuous(labels = num_lab)
    p
  })

  output$sa_plot <- renderPlot(sa_plot_obj(), res = 96)

  output$sa_clicked <- renderUI({
    req(input$sa_click)
    pt <- nearPoints(fitted_dat(), input$sa_click, xvar = "A", yvar = "S", maxpoints = 1, threshold = 15)
    if (!nrow(pt)) return(NULL)
    diff <- pt$S - pt$Predicted
    div(class = "alert alert-info mt-2 mb-0",
        strong(pt$Island), sprintf(": %s species, area %s. The line predicts %s species, so this island has %s %s species than expected.",
          num_lab(pt$S), num_lab(pt$A), fmt(pt$Predicted), fmt(abs(diff)), ifelse(diff >= 0, "more", "fewer")))
  })

  output$sa_interpret <- renderUI({
    zz <- z(); r2 <- summary(model())$r.squared
    zmsg <- if (zz < 0.15) "lower than the typical range for true islands (≈ 0.20–0.35). Lower z values are common for 'habitat islands' or islands close to a large source of colonists. Why might that be?"
            else if (zz <= 0.40) "within the typical range for oceanic islands (≈ 0.20–0.35)."
            else "higher than the typical range for islands (≈ 0.20–0.35). Very isolated archipelagos can give high z values."
    tagList(
      p(HTML(sprintf("<b>z = %s.</b> On a log–log plot, z is the slope of the line. Your z is %s", fmt(zz), zmsg))),
      p(HTML(sprintf("<b>Doubling the area</b> multiplies the number of species by 2<sup>z</sup> = <b>%s</b> (about %s%% more species).",
                     fmt(2^zz), round((2^zz - 1) * 100)))),
      p(HTML(sprintf("<b>R² = %s:</b> island area explains about %s%% of the variation in (log) species richness. The rest is due to other factors, which you'll explore on the next tab.",
                     fmt(r2, 2), round(r2 * 100))))
    )
  })

  code_r$code_sa <- reactive({
    S <- q(input$col_S); A <- q(input$col_A)
    plot_line <- if (input$loglog)
      sprintf(paste0('# Plot species (y) against area (x). log = "xy" puts both axes on a log scale;\n',
                     '# pch = 19 draws solid dots; xlab and ylab are the axis labels.\n',
                     'plot(%s ~ %s, data = dat, log = "xy", pch = 19,\n     xlab = "Island area", ylab = "Number of species")\n\n',
                     '# Add the fitted model as a straight red line (col = colour, lwd = line width)\n',
                     'abline(model, col = "red", lwd = 2)'), S, A)
    else
      sprintf(paste0('# Plot species (y) against area (x) on ordinary axes.\n',
                     '# pch = 19 draws solid dots; xlab and ylab are the axis labels.\n',
                     'plot(%s ~ %s, data = dat, pch = 19,\n     xlab = "Island area", ylab = "Number of species")\n\n',
                     '# Add the fitted curve S = c * A^z (on ordinary axes it is a curve, not a line)\n',
                     'curve(c * x^z, add = TRUE, col = "red", lwd = 2)'), S, A)
    paste0(
      "# Lines starting with # are comments: notes for people. R skips them.\n\n",
      "# Read the spreadsheet into R and call it 'dat'\n",
      read_cmd(), "\n\n",
      "# Keep only islands with more than 0 species and an area above 0,\n",
      "# because the log of 0 cannot be calculated. & means 'and'.\n",
      sprintf("dat <- subset(dat, %s > 0 & %s > 0)\n\n", S, A),
      "# Fit the species-area model as a straight line on log-log axes:\n",
      "#   log10(S) = log10(c) + z * log10(A)\n",
      "# lm() fits a straight line ('linear model'); y ~ x means 'y explained by x'.\n",
      sprintf("model <- lm(log10(%s) ~ log10(%s), data = dat)\n\n", S, A),
      "# Print the results. The 'Estimate' for log10(area) is z, the slope.\n",
      "# Pr(>|t|) is its p-value, and Multiple R-squared is R².\n",
      "summary(model)\n\n",
      "# coef(model) gives the two fitted numbers: [1] the intercept, [2] the slope.\n",
      "# The slope is z. The intercept is log10(c), so 10^ turns it back into c.\n",
      "# unname() just drops the label so only the number prints.\n",
      "z <- unname(coef(model)[2])\n",
      "c <- unname(10^coef(model)[1])\n\n",
      "# Typing a name on its own line prints its value\n",
      "z\nc\n\n",
      plot_line, "\n")
  })

  output$dl_sa <- downloadHandler(
    filename = function() "species_area_plot.png",
    content = function(file) ggsave(file, sa_plot_obj(), width = 8, height = 5.5, dpi = 200, bg = "white")
  )

  # ================= TAB 3: BEYOND AREA =================
  xinfo <- reactive({
    if (input$xvar == "D") list(col = input$col_D, label = "isolation") else list(col = input$col_X, label = "other variable")
  })

  resid_dat <- reactive({
    xi <- xinfo()
    validate(need(nzchar(xi$col), sprintf("Choose a column for the %s on the Data tab first.", xi$label)))
    d <- fitted_dat()
    d$x <- if (input$xvar == "D") d$D else d$X
    d <- subset(d, is.finite(x))
    if (input$logx) d <- subset(d, x > 0)
    validate(need(nrow(d) >= 3, "Not enough islands with values for this variable."))
    d
  })

  resid_model <- reactive({
    d <- resid_dat()
    if (input$logx) lm(Residual ~ log10(x), data = d) else lm(Residual ~ x, data = d)
  })

  output$resid_plot <- renderPlot({
    d <- resid_dat()
    p <- ggplot(d, aes(x, Residual)) +
      geom_hline(yintercept = 0, linetype = "dashed", colour = "grey40") +
      geom_point(size = 3, colour = "#6B8F9C", alpha = 0.9) +
      geom_smooth(method = "lm", formula = y ~ x, se = TRUE, colour = "#C55A11", fill = "#F4B183") +
      annotate("text", x = -Inf, y = Inf, label = "  more species than expected", hjust = 0, vjust = 1.5, colour = "grey40") +
      annotate("text", x = -Inf, y = -Inf, label = "  fewer species than expected", hjust = 0, vjust = -0.8, colour = "grey40") +
      labs(x = xinfo()$col, y = "Observed vs. predicted\n(log10 difference)") +
      theme_minimal(base_size = 15)
    if (input$logx) p <- p + scale_x_log10(labels = num_lab)
    p
  }, res = 96)

  output$resid_stats <- renderUI({
    s <- summary(resid_model())$coefficients
    slope <- s[2, 1]; p <- s[2, 4]; r2 <- summary(resid_model())$r.squared
    verdict <- if (p < 0.05) {
      sprintf("There <b>is</b> a statistically significant relationship (p %s). Islands with higher %s tend to have <b>%s</b> species than their area alone predicts.",
              ifelse(p < 0.001, "&lt; 0.001", paste("=", fmt_p(p))), xinfo()$col, ifelse(slope > 0, "more", "fewer"))
    } else {
      sprintf("There is <b>no</b> statistically significant relationship (p = %s). Once area is accounted for, %s does not clearly explain the remaining variation in species richness.",
              fmt_p(p), xinfo()$col)
    }
    div(class = "alert alert-light mt-2 mb-0", HTML(sprintf("%s &nbsp;<span class='text-muted small'>(slope = %s, R² = %s)</span>", verdict, fmt(slope), fmt(r2, 2))))
  })

  output$resid_table <- renderDT({
    d <- resid_dat()
    tab <- data.frame(Island = d$Island, Observed = d$S, Predicted = round(d$Predicted, 1),
                      Difference = round(d$S - d$Predicted, 1), check.names = FALSE)
    tab[[xinfo()$col]] <- d$x
    tab <- tab[order(-tab$Difference), ]
    datatable(tab, rownames = FALSE, options = list(pageLength = 8, scrollX = TRUE))
  })

  code_r$code_resid <- reactive({
    S <- q(input$col_S); A <- q(input$col_A); X <- q(xinfo()$col)
    xterm <- if (input$logx) sprintf("log10(%s)", X) else X
    paste0(
      "# Lines starting with # are comments: notes for people. R skips them.\n\n",
      "# Read the data and keep islands with species and area above 0 (log of 0 is impossible)\n",
      read_cmd(), "\n",
      sprintf("dat <- subset(dat, %s > 0 & %s > 0)\n\n", S, A),
      "# Fit the species-area line, as on the Species-Area tab\n",
      sprintf("model <- lm(log10(%s) ~ log10(%s), data = dat)\n\n", S, A),
      "# A residual is how far each island sits above (+) or below (-) the line:\n",
      "# positive = more species than its area predicts. Save them as a new column.\n",
      "dat$residual <- residuals(model)\n\n",
      "# Plot the residuals against the other variable.\n",
      sprintf("# %s\n", if (input$logx) 'log = "x" puts the x-axis on a log scale; pch = 19 draws solid dots.' else "pch = 19 draws solid dots."),
      sprintf("plot(residual ~ %s, data = dat, pch = 19%s)\n\n", X, if (input$logx) ', log = "x"' else ""),
      "# Draw a dashed line at 0 (h = horizontal, lty = 2 means dashed)\n",
      "abline(h = 0, lty = 2)\n\n",
      "# Test whether the residuals change with the other variable:\n",
      "# fit a second straight line, residual explained by that variable\n",
      sprintf("model2 <- lm(residual ~ %s, data = dat)\n\n", xterm),
      "# Look at the p-value (Pr(>|t|)) for the slope: below 0.05 means a significant relationship\n",
      "summary(model2)\n")
  })

  output$dl_resid <- downloadHandler(
    filename = function() "island_results.csv",
    content = function(file) {
      d <- fitted_dat()
      write.csv(data.frame(Island = d$Island, Species = d$S, Area = d$A,
                           Predicted = round(d$Predicted, 2), Difference = round(d$S - d$Predicted, 2),
                           Isolation = d$D, Other = d$X), file, row.names = FALSE)
    })

  # ================= TAB 4: PREDICT =================
  # Start the area box at a sensible value for whatever units the data uses
  observeEvent(list(raw(), input$col_A), {
    a <- used()$A
    if (length(a)) updateNumericInput(session, "new_area", value = signif(median(a), 2),
                                      label = paste0("Island area (", input$col_A, ")"))
  })

  output$pred_out <- renderUI({
    req(input$new_area > 0)
    s <- cc() * input$new_area^z()
    tagList(
      h2(class = "text-primary", sprintf("≈ %s species", fmt(s))),
      p(class = "text-muted", HTML(sprintf("S = c × A<sup>z</sup> = %s × %s<sup>%s</sup>", fmt(cc()), num_lab(input$new_area), fmt(z())))),
      p(class = "small text-muted", sprintf("Your data covers areas from %s to %s. Predictions far outside that range are less reliable.",
                                           num_lab(min(used()$A)), num_lab(max(used()$A))))
    )
  })

  output$loss_out <- renderUI({
    remain <- (1 - input$loss / 100)^z()
    tagList(
      h2(class = "text-danger", sprintf("≈ %s%% of species lost", round((1 - remain) * 100))),
      p(class = "text-muted", HTML(sprintf("Fraction of species remaining = (1 − %s)<sup>z</sup> = %s",
                                           input$loss / 100, fmt(remain))))
    )
  })

  output$loss_plot <- renderPlot({
    lossv <- seq(0, 99, 1)
    d <- data.frame(loss = lossv, lost = (1 - (1 - lossv / 100)^z()) * 100)
    ggplot(d, aes(loss, lost)) +
      geom_line(colour = "#B5523B", linewidth = 1.2) +
      geom_abline(slope = 1, intercept = 0, linetype = "dotted", colour = "grey50") +
      geom_point(data = data.frame(loss = input$loss, lost = (1 - (1 - input$loss / 100)^z()) * 100),
                 size = 4, colour = "#B5523B") +
      labs(x = "% of habitat lost", y = "% of species lost") +
      coord_cartesian(ylim = c(0, 100)) +
      theme_minimal(base_size = 13)
  }, res = 96)

  code_r$code_pred <- reactive({
    S <- q(input$col_S); A <- q(input$col_A)
    paste0(
      "# Lines starting with # are comments: notes for people. R skips them.\n\n",
      "# Read the data, keep islands with species and area above 0, and fit the species-area line\n",
      read_cmd(), "\n",
      sprintf("dat <- subset(dat, %s > 0 & %s > 0)\n", S, A),
      sprintf("model <- lm(log10(%s) ~ log10(%s), data = dat)\n\n", S, A),
      "# Pull out z (the slope) and c (10 to the power of the intercept)\n",
      "z <- unname(coef(model)[2])\n",
      "c <- unname(10^coef(model)[1])\n\n",
      "# Predict the number of species on a new island with S = c * A^z.\n",
      "# ^ means 'to the power of'. Change new_area and run the code again.\n",
      sprintf("new_area <- %s\n", input$new_area),
      "c * new_area^z\n\n",
      "# Habitat loss: if a fraction of the habitat is destroyed, the fraction of\n",
      "# species that eventually remains is (1 - fraction lost)^z.\n",
      "# loss is a fraction: 0.5 means 50% of the habitat is destroyed.\n",
      sprintf("loss <- %s\n", input$loss / 100),
      "remaining <- (1 - loss)^z\n\n",
      "# Fraction of species eventually lost (multiply by 100 for a percentage)\n",
      "1 - remaining\n")
  })

  # ================= EDITABLE CODE BOXES =================
  # Each box starts with the app's code. Students can edit it and press Run.
  for (cid in names(code_r)) local({
    id <- cid
    edit_id <- paste0(id, "_edit")

    result <- reactiveVal(NULL)

    # Refill the editor with the working code whenever the app's code changes
    observe(updateTextAreaInput(session, edit_id, value = code_r[[id]]()))

    # Reset: put the original, working code back and clear any old output / errors
    observeEvent(input[[paste0(id, "_reset")]], {
      updateTextAreaInput(session, edit_id, value = code_r[[id]]())
      result(NULL)
      showNotification("Code reset to the original working version.", type = "message", duration = 3)
    })

    # Run: R receives exactly what is in the editor
    observeEvent(input[[paste0(id, "_submit")]], {
      result(run_student_code(input[[paste0(id, "_submit")]]$code))
    })

    output[[paste0(id, "_out")]] <- renderUI({
      r <- result()
      if (is.null(r)) return(NULL)
      tagList(
        if (length(r$text)) tags$pre(class = if (r$error) "run-out run-error" else "run-out", paste(r$text, collapse = "\n"))
        else if (!r$error && is.null(r$plot) && is.null(r$widget)) tags$p(class = "small text-muted", "Your code ran. (It didn't print anything. Type a variable's name on its own line to see its value.)"),
        if (!is.null(r$plot)) tags$img(src = r$plot, class = "run-plot"),
        if (!is.null(r$widget)) div(class = "run-widget", r$widget)
      )
    })
  })
}

# ---- Run a student's code safely and collect what it prints / draws ----------
run_student_code <- function(code) {
  op <- options(scipen = 10)   # print 500, not 5e+02
  on.exit(options(op), add = TRUE)
  env <- new.env(parent = globalenv())
  text <- character(); widget <- NULL; error <- FALSE
  png_file <- tempfile(fileext = ".png")
  grDevices::png(png_file, width = 900, height = 600, res = 110)
  dev <- grDevices::dev.cur()
  grDevices::dev.control("enable")

  exprs <- tryCatch(parse(text = code), error = function(e) e)
  if (inherits(exprs, "error")) {
    grDevices::dev.off(dev)
    msg <- sub("^<text>:", "line ", conditionMessage(exprs))
    return(list(text = c("R couldn't read your code. Check for a typo, a missing bracket ), or a missing quote \".",
                         "", msg), error = TRUE, plot = NULL, widget = NULL))
  }

  for (e in exprs) {
    step <- tryCatch(
      withCallingHandlers({
        printed <- utils::capture.output(v <- withVisible(eval(e, env)))
        if (v$visible) {
          if (inherits(v$value, "htmlwidget")) widget <- v$value
          else printed <- c(printed, utils::capture.output(print(v$value)))
        }
        printed
      },
      warning = function(w) { text <<- c(text, paste("Warning:", conditionMessage(w))); invokeRestart("muffleWarning") },
      message = function(m) { text <<- c(text, sub("\n$", "", conditionMessage(m))); invokeRestart("muffleMessage") }),
      error = function(err) err)
    if (inherits(step, "error")) {
      text <- c(text, paste0("Error in this line:  ", paste(deparse(e), collapse = " ")),
                paste0("R says: ", conditionMessage(step)))
      error <- TRUE
      break
    }
    text <- c(text, step)
  }

  drew <- length(grDevices::recordPlot()[[1]]) > 0
  grDevices::dev.off(dev)
  plot <- if (drew) base64enc_png(png_file) else NULL
  list(text = text, error = error, plot = plot, widget = widget)
}

# Turn a PNG file into a data URI so it can be shown with <img>
base64enc_png <- function(path) {
  paste0("data:image/png;base64,", jsonlite::base64_enc(readBin(path, "raw", file.info(path)$size)))
}

